        QuizQuestion(75, QuizLevel.Intermediate, "ACPの内容を記録する際に重要なのはどちらか。", listOf("本人の発言や希望をできるだけ正確に記録する", "医療従事者の解釈だけを記録する"), 0, "本人が実際にどのような言葉で希望を伝えたかを記録することは、後の意思決定に役立ちます。"),
        QuizQuestion(76, QuizLevel.Intermediate, "本人の希望が以前のACPの記録と異なる場合、どうするべきか。", listOf("以前の記録を優先する", "現在の意思を確認し、必要に応じて記録を更新する"), 1, "本人の価値観や希望は変化するため、現在の意思を尊重することが重要です。"),
        QuizQuestion(77, QuizLevel.Intermediate, "ACPで家族が本人の希望に反対した場合、適切な対応はどちらか。", listOf("本人と家族それぞれの考えを丁寧に確認する", "家族の反対を理由に本人の希望を無視する"), 0, "意見が異なる背景を理解し、本人の意思を基本として合意形成を支援します。"),
        QuizQuestion(78, QuizLevel.Intermediate, "ACPで「家族に迷惑をかけたくない」と本人が話した場合、適切なのはどちらか。", listOf("その発言だけで治療拒否と判断する", "具体的に何を心配しているのか確認する"), 1, "経済的負担や介護負担など、心配の内容は人によって異なります。発言の背景を理解することが重要です。"),
        QuizQuestion(79, QuizLevel.Intermediate, "ACPにおいて看護師が果たす役割として適切なのはどちらか。", listOf("本人の思いを聞き取り、医療・ケアチームと共有する", "本人の意思を確認せず治療方針を決定する"), 0, "看護師は日常的な関わりを通じて本人の希望を把握し、意思決定を支援する役割を担います。"),
        QuizQuestion(80, QuizLevel.Intermediate, "ACPで本人が「自宅で過ごしたい」と希望した場合、適切な対応はどちらか。", listOf("必ず自宅療養を実現すると約束する", "希望を尊重し、利用できる支援や実現可能性を検討する"), 1, "本人の希望を大切にしながら、病状、介護体制、地域のサービスなどを確認する必要があります。"),
        QuizQuestion(81, QuizLevel.Intermediate, "ACPの話し合いで本人が治療内容を理解していない場合、適切なのはどちらか。", listOf("理解できるように説明を工夫する", "理解していなくても同意を求める"), 0, "本人が納得して意思決定できるよう、説明方法や情報量を調整します。"),
        QuizQuestion(82, QuizLevel.Intermediate, "ACPでは、本人の希望が明確であれば医学的な説明は不要である。", listOf("正しい", "間違い"), 1, "希望を具体的な医療・ケアにつなげるには、治療の効果や負担などについて十分な情報提供が必要です。"),
        QuizQuestion(83, QuizLevel.Intermediate, "ACPにおいて医療ソーシャルワーカーが支援できる内容はどちらか。", listOf("社会資源や経済的問題に関する相談", "本人の希望を無視した治療の決定"), 0, "医療ソーシャルワーカーは、生活上の課題や社会制度の利用などについて支援できます。"),
        QuizQuestion(84, QuizLevel.Intermediate, "ACPで本人が家族に病状を知らせたくない場合、適切なのはどちらか。", listOf("家族には必ずすべて知らせる", "本人の意思や情報共有の範囲を確認する"), 1, "家族との情報共有は重要ですが、本人のプライバシーや希望への配慮が必要です。"),
        QuizQuestion(85, QuizLevel.Intermediate, "ACPでは、本人が意思決定できる状態かどうかを確認することが重要である。", listOf("正しい", "間違い"), 0, "意思決定能力は状況や判断内容によって異なる場合があります。必要な支援を行いながら確認します。"),
        QuizQuestion(86, QuizLevel.Intermediate, "認知症と診断された人は、ACPに参加できない。", listOf("正しい", "間違い"), 1, "認知症があっても意思を表明できる場合があります。本人の能力に応じた意思決定支援が重要です。"),
        QuizQuestion(87, QuizLevel.Intermediate, "ACPで本人の意思を確認する際に適切な質問はどちらか。", listOf("「これからの生活で何を大切にしたいですか」", "「先生の考えに従いますよね」"), 0, "自由に答えられる質問は、本人の価値観や希望を引き出すのに役立ちます。"),
        QuizQuestion(88, QuizLevel.Intermediate, "ACPでは、本人が医療従事者と異なる意見を述べることは避けるべきである。", listOf("正しい", "間違い"), 1, "異なる意見も尊重し、その理由を理解することが重要です。"),
        QuizQuestion(89, QuizLevel.Intermediate, "ACPの話し合いで家族が涙を流した場合、適切な対応はどちらか。", listOf("気持ちを受け止め、必要に応じて時間を取る", "感情的になっているため参加を禁止する"), 0, "ACPでは本人や家族が不安や悲しみを感じることがあります。感情への配慮も重要です。"),
        QuizQuestion(90, QuizLevel.Intermediate, "ACPで本人が希望する医療と医学的に提供できる医療が異なる場合、どうするべきか。", listOf("本人の希望を無条件ですべて実施する", "医学的な状況を説明し、実現可能な選択肢を話し合う"), 1, "本人の希望を尊重しつつ、医学的な妥当性や適切性を踏まえて検討します。"),
        QuizQuestion(91, QuizLevel.Intermediate, "ACPにおいて、本人が信頼する人をあらかじめ決めておくことは役立つ。", listOf("正しい", "間違い"), 0, "本人が意思を伝えられなくなった場合、その人が本人の考えを医療・ケアチームに伝える助けになります。"),
        QuizQuestion(92, QuizLevel.Intermediate, "本人が意思表示できなくなった場合、過去のACPの記録だけで必ず治療を決定する。", listOf("正しい", "間違い"), 1, "過去の記録は重要な参考資料ですが、現在の医学的状況や本人の推定意思なども踏まえて検討します。"),
        QuizQuestion(93, QuizLevel.Intermediate, "ACPの話し合いでは、本人の希望する生活と治療の関係を確認することが重要である。", listOf("正しい", "間違い"), 0, "治療によって何を実現したいのかを理解することで、本人にとって意味のある選択を考えられます。"),
        QuizQuestion(94, QuizLevel.Intermediate, "ACPでは、医療従事者が本人の価値観を評価し、正しい価値観に修正する必要がある。", listOf("正しい", "間違い"), 1, "価値観は人それぞれ異なります。医療従事者が一方的に優劣をつけるものではありません。"),
        QuizQuestion(95, QuizLevel.Intermediate, "ACPで本人が「苦痛をできるだけ減らしたい」と希望した場合、検討すべきものはどちらか。", listOf("緩和ケアなどの苦痛軽減方法", "本人の希望に関係なく治療だけを続けること"), 0, "痛みや呼吸困難、不安などを軽減するための支援を検討します。"),
        QuizQuestion(96, QuizLevel.Intermediate, "緩和ケアは、積極的な治療をすべて終了してからしか受けられない。", listOf("正しい", "間違い"), 1, "緩和ケアは病気の治療と並行して提供されることもあります。"),
        QuizQuestion(97, QuizLevel.Intermediate, "ACPでは、治療の利益だけでなく負担や不利益についても説明する必要がある。", listOf("正しい", "間違い"), 0, "本人が十分な情報に基づいて判断するためには、期待される効果と負担の両方を理解することが重要です。"),
        QuizQuestion(98, QuizLevel.Intermediate, "ACPで本人が治療を希望しない場合、理由を確認せずにすべての医療を中止する。", listOf("適切である", "適切ではない"), 1, "何を希望しないのか、どのような理由があるのかを確認し、必要な医療やケアについて話し合います。"),
        QuizQuestion(99, QuizLevel.Intermediate, "ACPでは、本人の文化的背景に配慮することが重要である。", listOf("正しい", "間違い"), 0, "文化や宗教、家庭環境などによって、医療や人生の最終段階に対する考え方は異なります。"),
        QuizQuestion(100, QuizLevel.Intermediate, "ACPの話し合いでは、本人の発言が曖昧な場合でも確認せずに記録するべきである。", listOf("正しい", "間違い"), 1, "本人が何を意味しているのか丁寧に確認し、誤解を防ぐことが重要です。"),
        QuizQuestion(101, QuizLevel.Intermediate, "ACPにおいて、医療・ケアチーム内で情報共有する目的はどちらか。", listOf("本人の希望を踏まえた一貫性のある支援につなげるため", "本人に相談せず医療従事者だけで決めるため"), 0, "必要な範囲で情報を共有することで、関係者が本人の希望を理解しやすくなります。"),
        QuizQuestion(102, QuizLevel.Intermediate, "ACPで本人が「家族に決めてほしい」と話した場合、本人の意思決定支援は不要になる。", listOf("正しい", "間違い"), 1, "家族に判断を委ねたいという希望も尊重しつつ、どの範囲を任せたいのか確認することが重要です。"),
        QuizQuestion(103, QuizLevel.Intermediate, "ACPの話し合いで重要なコミュニケーション方法はどちらか。", listOf("相手の話を丁寧に聞く", "医療従事者が一方的に説明し続ける"), 0, "傾聴は本人の気持ちや価値観を理解するための基本的な姿勢です。"),
        QuizQuestion(104, QuizLevel.Intermediate, "ACPの記録は、本人の希望が変わっても更新する必要はない。", listOf("正しい", "間違い"), 1, "希望の変化を記録に反映することで、古い情報に基づいた判断を防ぎます。"),
        QuizQuestion(105, QuizLevel.Intermediate, "ACPでは、本人が理解しやすい言語や表現を使用することが望ましい。", listOf("正しい", "間違い"), 0, "必要に応じて通訳や説明資料を活用し、本人が理解できるよう支援します。"),
        QuizQuestion(106, QuizLevel.Intermediate, "ACPでは、家族がいない人は話し合いを行うことができない。", listOf("正しい", "間違い"), 1, "家族がいなくてもACPは可能です。本人が信頼する人や医療・ケアチームと話し合うことができます。"),
        QuizQuestion(107, QuizLevel.Intermediate, "ACPでは、本人が将来の医療について考えるための時間を確保することが重要である。", listOf("正しい", "間違い"), 0, "重要な判断を急がせず、本人が考えたり相談したりする時間を確保します。"),
        QuizQuestion(108, QuizLevel.Intermediate, "ACPの話し合いでは、本人の不安を軽減するために病状について嘘を伝えてもよい。", listOf("正しい", "間違い"), 1, "本人の知りたい程度や心理状態に配慮しながら、誠実に情報提供することが重要です。"),
        QuizQuestion(109, QuizLevel.Intermediate, "ACPでは、本人の希望を実現するために介護職の意見が役立つ場合がある。", listOf("正しい", "間違い"), 0, "介護職は日常生活の様子を把握していることが多く、本人の価値観や生活上の希望を理解する助けになります。"),
        QuizQuestion(110, QuizLevel.Intermediate, "ACPで本人が希望する療養場所を決めたら、その後は変更できない。", listOf("正しい", "間違い"), 1, "病状や生活環境、本人の気持ちの変化に応じて希望を見直すことができます。"),
        QuizQuestion(111, QuizLevel.Intermediate, "ACPでは、医療・ケアチームが本人の希望を理解するために繰り返し話し合うことがある。", listOf("正しい", "間違い"), 0, "継続的な対話によって、本人の希望や価値観をより深く理解できます。"),
        QuizQuestion(112, QuizLevel.Intermediate, "ACPの話し合いでは、本人が感情的になった場合、必ず話し合いを打ち切る。", listOf("正しい", "間違い"), 1, "本人の感情を受け止め、休憩や日程変更などを含めて柔軟に対応します。"),
        QuizQuestion(113, QuizLevel.Intermediate, "ACPで本人の希望を確認する際、治療を受けることで実現したい目標を聞くことは有用である。", listOf("正しい", "間違い"), 0, "「家族と過ごしたい」「趣味を続けたい」などの目標は、治療方針を考える手がかりになります。"),
        QuizQuestion(114, QuizLevel.Intermediate, "ACPにおいて、本人の希望と医学的判断が異なる場合は話し合いを避けるべきである。", listOf("正しい", "間違い"), 1, "意見が異なる場合こそ、医学的な説明と本人の価値観の確認を重ねる必要があります。"),
        QuizQuestion(115, QuizLevel.Intermediate, "ACPの話し合いでは、本人が大切にしている人間関係について確認することがある。", listOf("正しい", "間違い"), 0, "誰と過ごしたいか、誰に支えてほしいかといった希望も、本人らしい生活を考えるうえで重要です。"),
        QuizQuestion(116, QuizLevel.Intermediate, "ACPでは、本人の意思が確認できる場合でも、医療従事者の判断だけで治療方針を決定することが基本である。", listOf("正しい", "間違い"), 1, "本人への説明と話し合いを通じて意思決定することが基本です。"),
        QuizQuestion(117, QuizLevel.Intermediate, "ACPで本人が「できるだけ長く生きたい」と希望した場合、適切なのはどちらか。", listOf("どのような治療や生活を望むのか、さらに確認する", "本人の希望を無視して治療を制限する"), 0, "長く生きたいという希望の背景や、本人が重視する生活の質について理解することが重要です。"),
        QuizQuestion(118, QuizLevel.Intermediate, "ACPで本人が「自然に任せたい」と話した場合、すべての医療行為を拒否していると判断できる。", listOf("判断できる", "その発言だけでは判断できない"), 1, "「自然に任せたい」という言葉の意味は人によって異なります。具体的な希望を確認する必要があります。"),
        QuizQuestion(119, QuizLevel.Intermediate, "ACPの話し合いでは、本人が抱える経済的な不安も確認してよい。", listOf("正しい", "間違い"), 0, "経済的な不安は医療や療養場所の選択に影響することがあります。必要に応じて相談支援につなげます。"),
        QuizQuestion(120, QuizLevel.Intermediate, "ACPで本人が治療を拒否した場合、その人へのケアもすべて終了する。", listOf("正しい", "間違い"), 1, "特定の治療を希望しない場合でも、苦痛緩和や生活支援など必要なケアは継続して検討します。"),
        QuizQuestion(121, QuizLevel.Intermediate, "ACPにおいて、医療・ケアチームが本人の価値観を共有することは重要である。", listOf("正しい", "間違い"), 0, "本人の価値観を共有することで、職種が異なっても本人の希望に沿った支援を行いやすくなります。"),
        QuizQuestion(122, QuizLevel.Intermediate, "ACPでは、本人が一度同意した治療について、後から撤回することはできない。", listOf("正しい", "間違い"), 1, "本人は状況に応じて意思を変更できます。ただし、実施済みの医療行為を元に戻せるわけではありません。"),
        QuizQuestion(123, QuizLevel.Intermediate, "ACPで家族の意見が分かれた場合、適切なのはどちらか。", listOf("本人の意思や価値観を中心に話し合う", "最も声の大きい家族の意見を採用する"), 0, "家族間の意見の違いを整理し、本人が何を望んでいたかを考えることが重要です。"),
        QuizQuestion(124, QuizLevel.Intermediate, "ACPでは、本人の意思が不明な場合、家族の希望をそのまま本人の希望とみなしてよい。", listOf("正しい", "間違い"), 1, "家族の希望と本人の希望は必ずしも同じではありません。本人の過去の発言や価値観などを確認します。"),
        QuizQuestion(125, QuizLevel.Intermediate, "ACPの記録には、話し合いに参加した人を記載することが役立つ。", listOf("正しい", "間違い"), 0, "誰が参加し、どのような内容を共有したかを残すことで、後から経緯を確認できます。"),
        QuizQuestion(126, QuizLevel.Intermediate, "ACPでは、本人の意思決定能力を年齢だけで判断してよい。", listOf("正しい", "間違い"), 1, "意思決定能力は年齢だけでは判断できません。理解力や判断内容、必要な支援などを考慮します。"),
        QuizQuestion(127, QuizLevel.Intermediate, "ACPでは、本人の希望を確認するために日常生活での会話が役立つことがある。", listOf("正しい", "間違い"), 0, "普段の会話から、本人が何を大切にしているかを知ることができます。"),
        QuizQuestion(128, QuizLevel.Intermediate, "ACPは、医療機関を変更した場合には最初からすべてやり直さなければならない。", listOf("正しい", "間違い"), 1, "本人の同意を得てこれまでの記録を共有し、現在の希望を確認しながら継続できます。"),
        QuizQuestion(129, QuizLevel.Intermediate, "ACPで本人が「痛みを我慢したくない」と話した場合、痛みの管理について相談することは適切である。", listOf("正しい", "間違い"), 0, "本人が重視する苦痛の軽減について、適切な医療やケアの方法を検討します。"),
        QuizQuestion(130, QuizLevel.Intermediate, "ACPでは、本人が病状を詳しく知りたくないと希望した場合、その希望を無視してすべて説明するべきである。", listOf("正しい", "間違い"), 1, "本人がどの程度の情報を希望しているか確認し、その意思に配慮して説明を進めます。"),
        QuizQuestion(131, QuizLevel.Intermediate, "ACPでは、本人の希望を理解するために生活歴を確認することがある。", listOf("正しい", "間違い"), 0, "仕事、趣味、家族との関係など、これまでの人生を知ることで本人の価値観を理解しやすくなります。"),
        QuizQuestion(132, QuizLevel.Intermediate, "ACPにおいて、本人が理解できない説明を繰り返すだけで意思決定支援は十分である。", listOf("正しい", "間違い"), 1, "図や資料を使う、説明を分けるなど、本人に合った方法を工夫する必要があります。"),
        QuizQuestion(133, QuizLevel.Intermediate, "ACPでは、本人が希望する治療の負担についても考える必要がある。", listOf("正しい", "間違い"), 0, "治療による苦痛や副作用、生活への影響なども含めて検討します。"),
        QuizQuestion(134, QuizLevel.Intermediate, "ACPで本人が希望する治療が医学的に適切でない場合でも、医療従事者は必ず実施しなければならない。", listOf("正しい", "間違い"), 1, "本人の希望を尊重しながらも、医学的な適切性を踏まえて話し合う必要があります。"),
        QuizQuestion(135, QuizLevel.Intermediate, "ACPでは、本人の希望を支えるために地域包括支援センターなどの相談機関が役立つ場合がある。", listOf("正しい", "間違い"), 0, "地域包括支援センターは高齢者の生活や介護に関する相談を受け付けており、必要な支援につなぐ役割があります。"),
        QuizQuestion(136, QuizLevel.Intermediate, "ACPでは、本人の意思が明確であれば家族の感情には一切配慮する必要がない。", listOf("正しい", "間違い"), 1, "本人の意思を尊重することと、家族の不安や悲しみに配慮することは両立できます。"),
        QuizQuestion(137, QuizLevel.Intermediate, "ACPでは、本人が自分の考えを整理するために複数回の面談を行うことがある。", listOf("正しい", "間違い"), 0, "一度の話し合いで結論を出す必要はありません。時間をかけて考えることができます。"),
        QuizQuestion(138, QuizLevel.Intermediate, "ACPの話し合いは、本人の体調が悪いときほど長時間行うべきである。", listOf("正しい", "間違い"), 1, "本人の体調や疲労に配慮し、必要に応じて短時間に分けて実施します。"),
        QuizQuestion(139, QuizLevel.Intermediate, "ACPでは、本人が意思を伝えやすい環境を整えることが重要である。", listOf("正しい", "間違い"), 0, "静かな場所を選ぶ、プライバシーを確保するなどの配慮が必要です。"),
        QuizQuestion(140, QuizLevel.Intermediate, "ACPの話し合いでは、医療従事者が自分の価値観を本人に押し付けてもよい。", listOf("正しい", "間違い"), 1, "医療従事者は自分の価値観によって本人の選択を誘導しないよう注意する必要があります。"),
        QuizQuestion(141, QuizLevel.Intermediate, "ACPで本人が希望する治療について迷っている場合、適切なのはどちらか。", listOf("選択肢の利益と負担を整理して一緒に考える", "迷っているため医療従事者が説明せずに決定する"), 0, "本人が納得して選択できるよう、情報提供と意思決定支援を行います。"),
        QuizQuestion(142, QuizLevel.Intermediate, "ACPでは、本人の希望が家族に伝わっていれば、医療・ケアチームと共有する必要はない。", listOf("正しい", "間違い"), 1, "本人の同意を得たうえで、必要な関係者と情報共有することが重要です。"),
        QuizQuestion(143, QuizLevel.Intermediate, "ACPにおいて、本人が将来の治療について具体的に決められなくても、価値観を共有することには意味がある。", listOf("正しい", "間違い"), 0, "具体的な治療を決めていなくても、本人が何を大切にしているかは将来の判断に役立ちます。"),
        QuizQuestion(144, QuizLevel.Intermediate, "ACPでは、本人の意思が確認できない場合、最も高額な治療を選ぶことが基本である。", listOf("正しい", "間違い"), 1, "治療費の高低ではなく、本人の推定意思や最善の利益、医学的な適切性などを踏まえて検討します。"),
        QuizQuestion(145, QuizLevel.Intermediate, "ACPで本人が「家族と一緒に過ごす時間を大切にしたい」と希望した場合、療養環境を検討することは適切である。", listOf("正しい", "間違い"), 0, "面会のしやすさや療養場所などを考えることで、本人の希望を支援できる場合があります。"),
        QuizQuestion(146, QuizLevel.Intermediate, "ACPでは、本人が治療を希望しない場合、医療従事者はその理由を確認してはいけない。", listOf("正しい", "間違い"), 1, "本人の意思を尊重しながら、希望の背景や理解状況を丁寧に確認することが重要です。"),
        QuizQuestion(147, QuizLevel.Intermediate, "ACPでは、病状が変化した際に話し合いを見直すことが望ましい。", listOf("正しい", "間違い"), 0, "病状の変化によって治療の選択肢や本人の希望が変わる場合があります。"),
        QuizQuestion(148, QuizLevel.Intermediate, "ACPで家族が本人の希望を知らない場合、家族の推測だけで判断すれば十分である。", listOf("正しい", "間違い"), 1, "過去の発言や生活歴などを確認し、医療・ケアチームで慎重に検討する必要があります。"),
        QuizQuestion(149, QuizLevel.Intermediate, "ACPでは、本人が自分らしく生活できるよう医療と介護が連携することが重要である。", listOf("正しい", "間違い"), 0, "医療と介護の連携によって、本人の生活全体を支えることができます。"),
        QuizQuestion(150, QuizLevel.Intermediate, "ACPの最も重要な成果は、必ず一つの治療方針を決定することである。", listOf("正しい", "間違い"), 1, "ACPでは、結論を急ぐことよりも、本人の価値観や希望を理解し共有する過程が重要です。"),
        QuizQuestion(151, QuizLevel.Advanced, "本人が意思表示できない状態になった場合、ACPで共有された過去の希望はどのように扱うべきか。", listOf("本人の推定意思を考えるための重要な情報として扱う", "現在の意思ではないため、すべて無視する"), 0, "過去のACPの記録は本人の推定意思を考える重要な手がかりです。ただし、現在の病状や状況も踏まえて検討します。"),
        QuizQuestion(152, QuizLevel.Advanced, "本人が意思表示できず、家族も本人の希望を知らない場合、医療・ケアチームはどのように対応するべきか。", listOf("家族の中で最も年長の人にすべて決定してもらう", "本人にとっての最善の方針を医療・ケアチームで慎重に検討する"), 1, "本人の意思を推定できない場合、医学的な状況や本人の利益などを踏まえ、家族等とも話し合いながら方針を検討します。"),
        QuizQuestion(153, QuizLevel.Advanced, "ACPで本人が人工呼吸器を希望しないと話していた場合、その希望はどのように扱うべきか。", listOf("現在の状況と照らし合わせ、本人の意思を尊重するための重要な情報とする", "人工呼吸器は必ず使用しなければならないため、希望は無視する"), 0, "過去の希望を尊重しながら、本人がどのような状況を想定していたのか、現在の医学的状況と一致するかを確認します。"),
        QuizQuestion(154, QuizLevel.Advanced, "ACPで「延命治療を希望しない」と記録されていた場合、すべての医療行為を中止することが適切である。", listOf("正しい", "間違い"), 1, "「延命治療」という言葉が何を指すのかは人によって異なります。具体的な治療やケアについて確認し、適切な医療を継続する必要があります。"),
        QuizQuestion(155, QuizLevel.Advanced, "ACPにおける「本人の最善の利益」を考える際、本人の価値観を考慮することは重要である。", listOf("正しい", "間違い"), 0, "医学的な利益だけでなく、本人の生活歴、価値観、人生観なども踏まえて考える必要があります。"),
        QuizQuestion(156, QuizLevel.Advanced, "ACPで本人が治療を拒否した場合、その意思決定能力を確認せず、直ちに治療を中止することが常に適切である。", listOf("正しい", "間違い"), 1, "本人が治療内容や結果を理解しているか、判断に影響する要因がないかなどを確認し、適切な意思決定支援を行います。"),
        QuizQuestion(157, QuizLevel.Advanced, "ACPにおいて、本人の意思決定能力はすべての判断について一律に評価できる。", listOf("正しい", "間違い"), 1, "意思決定能力は判断内容の複雑さや本人の状態によって異なります。個々の意思決定について評価することが重要です。"),
        QuizQuestion(158, QuizLevel.Advanced, "認知症のある人がACPに参加する場合、適切な対応はどちらか。", listOf("本人の理解力に応じた説明や支援を行う", "認知症があるという理由だけで本人を話し合いから除外する"), 0, "認知症があっても本人が意思を表明できる場合があります。本人の残された能力を生かす支援が重要です。"),
        QuizQuestion(159, QuizLevel.Advanced, "本人が意思表示できない場合、家族が希望する治療は医学的に不適切でも必ず実施するべきである。", listOf("正しい", "間違い"), 1, "家族の希望を丁寧に聞くことは重要ですが、医学的な妥当性や本人の利益などを踏まえて検討します。"),
        QuizQuestion(160, QuizLevel.Advanced, "ACPにおいて、本人の希望と医療従事者の判断が対立した場合、適切なのはどちらか。", listOf("本人の希望を無条件に実施する", "双方の考えを確認し、必要に応じて多職種で検討する"), 1, "本人の意思を尊重しながら、医学的な適切性や倫理的な課題について十分に話し合う必要があります。"),
        QuizQuestion(161, QuizLevel.Advanced, "ACPで本人が心肺蘇生を希望しないと表明していた場合、DNARの指示があれば他の治療もすべて中止する。", listOf("正しい", "間違い"), 1, "DNARは一般に心停止時の心肺蘇生を行わないという指示であり、その他の治療やケアを一律に制限するものではありません。"),
        QuizQuestion(162, QuizLevel.Advanced, "DNARの方針が決まっている患者に対して、苦痛を和らげるためのケアを行うことは適切である。", listOf("適切である", "適切ではない"), 0, "DNARの方針があっても、疼痛緩和や呼吸困難への対応など、必要なケアを継続します。"),
        QuizQuestion(163, QuizLevel.Advanced, "ACPで本人が「人工呼吸器は使いたくない」と希望していた場合、すべての酸素療法も拒否していると判断できる。", listOf("判断できる", "判断できない"), 1, "人工呼吸器と酸素療法は異なる医療行為です。本人がどのような治療を想定していたのか確認する必要があります。"),
        QuizQuestion(164, QuizLevel.Advanced, "ACPでは、治療を開始しないことと、開始した治療を中止することについて、どちらも慎重な意思決定が必要である。", listOf("正しい", "間違い"), 0, "治療の不開始と中止はいずれも重要な医療上・倫理上の判断です。本人の意思や医学的状況を踏まえ、適切なプロセスで検討します。"),
        QuizQuestion(165, QuizLevel.Advanced, "ACPにおいて、医療従事者が本人に特定の治療を選ばせるため、意図的に不利益な情報を隠すことは適切である。", listOf("正しい", "間違い"), 1, "本人が適切に判断できるよう、治療の利益や負担について公平に情報提供することが重要です。"),
        QuizQuestion(166, QuizLevel.Advanced, "ACPで本人が「家族に負担をかけるくらいなら治療を受けたくない」と話した場合、適切な対応はどちらか。", listOf("家族への負担について具体的に確認し、利用できる支援も説明する", "本人が治療を希望していないため、それ以上確認しない"), 0, "本人が家族への負担を過大に心配している可能性もあります。介護サービスや経済的支援などの情報提供が役立つ場合があります。"),
        QuizQuestion(167, QuizLevel.Advanced, "ACPで本人が治療を拒否している場合、うつ状態などが判断に影響している可能性を検討することは適切である。", listOf("適切である", "適切ではない"), 0, "心理的な状態が意思決定に影響する場合があります。ただし、うつ状態があることだけで本人の意思を無効と判断してはいけません。"),
        QuizQuestion(168, QuizLevel.Advanced, "ACPで本人が「もう何もしたくない」と発言した場合、その言葉だけで積極的な治療をすべて拒否していると判断できる。", listOf("判断できる", "判断できない"), 1, "疲労、苦痛、不安、抑うつなどが背景にある可能性があります。発言の意味を丁寧に確認する必要があります。"),
        QuizQuestion(169, QuizLevel.Advanced, "ACPにおいて、本人の意思と家族の希望が対立した場合、本人に意思決定能力があれば、その意思を基本として考える。", listOf("正しい", "間違い"), 0, "本人の自己決定を尊重することが基本です。同時に家族の不安や意見にも配慮し、理解を得るための話し合いを行います。"),
        QuizQuestion(170, QuizLevel.Advanced, "ACPにおいて、本人の意思が確認できない場合、医療・ケアチームは家族の希望だけでなく本人の過去の価値観も考慮する。", listOf("正しい", "間違い"), 0, "過去の発言や生活歴、人生観などは、本人が何を望んでいたかを推定するための重要な情報です。"),
        QuizQuestion(171, QuizLevel.Advanced, "ACPで本人が以前は延命治療を希望していなかったが、現在は希望している場合、どちらを尊重するべきか。", listOf("以前の希望を必ず優先する", "現在の意思決定能力や理解状況を確認したうえで、現在の希望を尊重する"), 1, "本人の意思は変化することがあります。現在の本人が十分な理解のもとで表明した意思を尊重することが重要です。"),
        QuizQuestion(172, QuizLevel.Advanced, "ACPで本人が治療方針について家族に判断を任せたいと希望した場合、その希望も本人の自己決定の一つと考えられる。", listOf("正しい", "間違い"), 0, "自分で決めることだけでなく、信頼する人に判断を委ねることも本人の意思として尊重されます。"),
        QuizQuestion(173, QuizLevel.Advanced, "ACPにおいて、本人が「治療方針は家族に任せる」と話した場合、本人の価値観を確認する必要はなくなる。", listOf("正しい", "間違い"), 1, "家族が判断する場合でも、本人が何を大切にしているかを理解しておくことが役立ちます。"),
        QuizQuestion(174, QuizLevel.Advanced, "ACPでは、医療従事者が本人の希望を実現できない場合、その理由を説明することが重要である。", listOf("正しい", "間違い"), 0, "希望を実現できない理由や代替案を説明し、本人が納得できる方針を一緒に考えることが重要です。"),
        QuizQuestion(175, QuizLevel.Advanced, "ACPで本人が希望する療養場所と、家族が介護できる環境が一致しない場合、どのように対応するべきか。", listOf("本人の希望を無視して施設入所を決定する", "本人と家族の状況を確認し、利用できる支援を含めて検討する"), 1, "本人の希望と家族の介護負担の両方を考慮し、在宅サービスなどを活用できるか検討します。"),
        QuizQuestion(176, QuizLevel.Advanced, "ACPでは、医療従事者が本人の意思決定能力を支援によって高められる可能性を考慮することが重要である。", listOf("正しい", "間違い"), 0, "説明方法を工夫したり、適切な時間帯に話し合ったりすることで、本人が判断しやすくなる場合があります。"),
        QuizQuestion(177, QuizLevel.Advanced, "せん妄によって意思決定が難しくなっている患者について、回復が見込める場合でも、その時点の発言だけで将来の治療方針を固定するべきである。", listOf("正しい", "間違い"), 1, "せん妄は一時的に意思決定能力へ影響することがあります。緊急性や病状を考慮し、可能であれば状態の改善後に意思を確認します。"),
        QuizQuestion(178, QuizLevel.Advanced, "ACPにおいて、本人の意思が不明で家族間の意見も対立している場合、適切な対応はどちらか。", listOf("必要に応じて倫理的な検討の場を設ける", "医療従事者が独断で決定し、家族には説明しない"), 0, "複雑な事例では、多職種による検討や倫理コンサルテーションなどを活用することが有用です。"),
        QuizQuestion(179, QuizLevel.Advanced, "ACPにおける倫理的な検討では、本人の意思だけでなく医学的な妥当性や家族の状況も考慮する必要がある。", listOf("正しい", "間違い"), 0, "本人の意思を基本としながら、医学的な利益と負担、生活環境、家族の状況などを総合的に検討します。"),
        QuizQuestion(180, QuizLevel.Advanced, "ACPでは、本人の意思が確認できない場合、医療従事者の個人的な価値観を最優先して治療方針を決める。", listOf("正しい", "間違い"), 1, "医療従事者個人の価値観ではなく、本人の推定意思や最善の利益、医学的な適切性などに基づいて検討します。"),
        QuizQuestion(181, QuizLevel.Advanced, "ACPで本人が「最期まで食事を楽しみたい」と希望している場合、嚥下機能が低下していても本人の希望と安全性を両方検討することが重要である。", listOf("正しい", "間違い"), 0, "誤嚥の危険性などを評価しながら、食事形態の工夫や支援方法について多職種で検討します。"),
        QuizQuestion(182, QuizLevel.Advanced, "ACPで本人が経口摂取を希望している場合、誤嚥の危険性があっても必ず普通食を提供しなければならない。", listOf("正しい", "間違い"), 1, "本人の希望を尊重しながら、嚥下機能や誤嚥の危険性を評価し、安全性に配慮した方法を検討します。"),
        QuizQuestion(183, QuizLevel.Advanced, "ACPで本人が人工的な栄養補給を希望しない場合、その意思の背景や具体的な治療内容を確認することが重要である。", listOf("正しい", "間違い"), 0, "胃ろうや経鼻経管栄養など、方法によって特徴や負担が異なります。本人が何を希望していないのか確認する必要があります。"),
        QuizQuestion(184, QuizLevel.Advanced, "ACPで胃ろうを希望しないと表明した人は、点滴による水分補給もすべて拒否していると判断できる。", listOf("判断できる", "判断できない"), 1, "胃ろうと点滴は異なる医療行為です。それぞれの希望について確認する必要があります。"),
        QuizQuestion(185, QuizLevel.Advanced, "ACPでは、治療を行うことによって本人の生活の質がどのように変化するかを考えることが重要である。", listOf("正しい", "間違い"), 0, "治療の効果だけでなく、生活の質への影響を考えることで、本人の価値観に沿った選択を支援できます。"),
        QuizQuestion(186, QuizLevel.Advanced, "ACPにおいて、本人が苦痛の少ない生活を希望している場合、生命予後だけを基準に治療を選択するべきである。", listOf("正しい", "間違い"), 1, "生命予後だけでなく、苦痛の程度や本人の希望、生活の質なども考慮する必要があります。"),
        QuizQuestion(187, QuizLevel.Advanced, "ACPで本人が在宅で最期を迎えたいと希望している場合、医療・介護サービスの利用可能性を確認することは重要である。", listOf("正しい", "間違い"), 0, "訪問診療、訪問看護、介護サービス、緊急時の対応体制などを確認し、希望の実現を支援します。"),
        QuizQuestion(188, QuizLevel.Advanced, "ACPで本人が自宅での療養を希望している場合、家族が介護できない状況でも、必ず自宅療養を選択しなければならない。", listOf("正しい", "間違い"), 1, "本人の希望を尊重しながら、家族の状況や利用できる支援を踏まえ、実現可能な方法を検討します。"),
        QuizQuestion(189, QuizLevel.Advanced, "ACPで本人が「できるだけ家族と過ごしたい」と希望している場合、治療の選択肢を検討する際に入院期間も考慮することがある。", listOf("正しい", "間違い"), 0, "治療による入院期間や生活への影響は、本人が大切にしている家族との時間に関係します。"),
        QuizQuestion(190, QuizLevel.Advanced, "ACPで本人が治療を希望しないと表明した場合、医療従事者は本人が十分に理解しているか確認する必要はない。", listOf("正しい", "間違い"), 1, "本人が治療の効果や負担、治療を受けない場合の影響を理解しているか確認することが重要です。"),
        QuizQuestion(191, QuizLevel.Advanced, "ACPにおいて、本人の意思が確認できず、過去の希望も不明な場合、本人の最善の利益を考えるために多職種で検討することは適切である。", listOf("適切である", "適切ではない"), 0, "医師、看護師、介護職などがそれぞれの専門的な視点から検討することで、より適切な判断につながります。"),
        QuizQuestion(192, QuizLevel.Advanced, "ACPで本人の意思が確認できない場合、家族がいなければ医療・ケアの方針を決定することはできない。", listOf("正しい", "間違い"), 1, "家族がいない場合でも、医療・ケアチームが本人の利益を慎重に検討し、必要に応じて専門家の助言を得ながら方針を決定することができます。"),
        QuizQuestion(193, QuizLevel.Advanced, "ACPにおいて、本人が以前に示した希望と現在の医学的状況が大きく異なる場合、過去の希望をどのように解釈するか検討する必要がある。", listOf("正しい", "間違い"), 0, "本人が想定していた状況と実際の状況が異なる場合があります。希望の背景にある価値観を確認し、現在の状況に照らして検討します。"),
        QuizQuestion(194, QuizLevel.Advanced, "ACPで本人が「意識が戻らない状態なら延命治療を希望しない」と話していた場合、一時的な意識障害でも必ず治療を中止するべきである。", listOf("正しい", "間違い"), 1, "一時的な意識障害と回復の見込みがない状態は異なります。本人が想定していた状況と医学的な見通しを確認する必要があります。"),
        QuizQuestion(195, QuizLevel.Advanced, "ACPでは、本人の希望を実現するために医療・介護・福祉の関係者が連携することが重要である。", listOf("正しい", "間違い"), 0, "本人の希望は医療だけで実現できるとは限りません。介護や福祉など、さまざまな支援を組み合わせることが重要です。"),
        QuizQuestion(196, QuizLevel.Advanced, "ACPにおいて、本人が意思表示できない状態で家族が治療方針に強く反対している場合、十分な話し合いをせずに方針を決定することが望ましい。", listOf("正しい", "間違い"), 1, "家族の反対の背景を確認し、本人の推定意思や医学的な状況について丁寧に説明することが重要です。"),
        QuizQuestion(197, QuizLevel.Advanced, "ACPでは、本人が希望する医療・ケアについて、実現可能性だけでなく本人にとっての意味も考えることが重要である。", listOf("正しい", "間違い"), 0, "なぜその医療やケアを希望するのかを理解することで、本人の価値観に沿った代替案を考えられる場合があります。"),
        QuizQuestion(198, QuizLevel.Advanced, "ACPの話し合いで本人が希望を表明した場合、その希望は将来のあらゆる状況で必ず同じ意味を持つ。", listOf("正しい", "間違い"), 1, "希望の意味は病状や生活環境によって変わることがあります。具体的な状況に応じて解釈し、可能であれば本人に再確認します。"),
        QuizQuestion(199, QuizLevel.Advanced, "ACPにおいて、本人の意思を尊重することと、医療・ケアチームが医学的な適切性を判断することは両立できる。", listOf("正しい", "間違い"), 0, "本人の価値観や希望を尊重しながら、医学的な根拠に基づいて適切な医療・ケアを検討することが重要です。"),
        QuizQuestion(200, QuizLevel.Advanced, "ACPで最も重要な考え方として適切なのはどちらか。", listOf("将来の治療方針を一度決めたら、どのような状況でも変更しないこと", "本人の価値観や希望を尊重し、関係者と継続的に話し合いながら医療・ケアを考えること"), 1, "ACPの中心となるのは、本人の意思や価値観を尊重することです。本人の気持ちや医学的状況は変化するため、繰り返し話し合い、必要に応じて方針を見直していくことが大切です。")
    )
